class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        int best = 0;
        for (int split = 0; split < n; split++) {
            int left = once(prices, 0, split);
            int right = once(prices, split + 1, n - 1);
            best = Math.max(best, left + right);
        }
        return best;
    }

    private int once(int[] p, int lo, int hi) {
        if (lo > hi) return 0;
        int minPrice = Integer.MAX_VALUE;
        int profit = 0;
        for (int i = lo; i <= hi; i++) {
            profit = Math.max(profit, p[i] - minPrice);
            minPrice = Math.min(minPrice, p[i]);
        }
        return profit;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        if (n == 0) return 0;
        int[] left = new int[n];
        int[] right = new int[n];

        int minPrice = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            left[i] = Math.max(i > 0 ? left[i - 1] : 0, prices[i] - minPrice);
            minPrice = Math.min(minPrice, prices[i]);
        }

        int maxPrice = Integer.MIN_VALUE;
        for (int i = n - 1; i >= 0; i--) {
            right[i] = Math.max(i < n - 1 ? right[i + 1] : 0, maxPrice - prices[i]);
            maxPrice = Math.max(maxPrice, prices[i]);
        }

        int best = 0;
        for (int i = 0; i < n - 1; i++) {
            best = Math.max(best, left[i] + right[i + 1]);
        }
        return best;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int buy1 = Integer.MIN_VALUE / 2;
        int sell1 = 0;
        int buy2 = Integer.MIN_VALUE / 2;
        int sell2 = 0;

        for (int p : prices) {
            buy1 = Math.max(buy1, -p);
            sell1 = Math.max(sell1, buy1 + p);
            buy2 = Math.max(buy2, sell1 - p);
            sell2 = Math.max(sell2, buy2 + p);
        }
        return sell2;
    }
}
